using System;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 public sealed class MobileShell:MonoBehaviour {
  Image indicator;float indicatorX;bool located;GameRuntime game;public Sprite[] ResourceIcons;public LaboratoryView Laboratory;public void Initialize(GameRuntime runtime){game=runtime;var receipts=gameObject.AddComponent<RewardPresentation>();receipts.Initialize(game);Laboratory.Initialize(game);var menu=gameObject.AddComponent<GameMenu>();menu.Initialize(game);var safe=Laboratory.GetComponentInParent<SafeArea>().transform;var tabs=safe.Find("Tabs");indicator=WorkshopUIFactory.Node("ActiveNavigationMarker",tabs,typeof(Image),typeof(LayoutElement)).GetComponent<Image>();indicator.GetComponent<LayoutElement>().ignoreLayout=true;indicator.raycastTarget=false;indicator.color=GameTheme.Accent;indicator.rectTransform.anchorMin=indicator.rectTransform.anchorMax=new Vector2(.5f,0);indicator.rectTransform.sizeDelta=new Vector2(52,3);var button=safe.Find("Header/Menu");if(button!=null)button.GetComponent<Button>().onClick.AddListener(menu.Open);}
  void LateUpdate(){if(game?.State==null)return;var s=game.State;var tabs=new[]{game.HardwareTab,game.TrainingTab,game.ResearchTab,game.ItemsTab,game.PrestigeTab};string[] names={"hardware","training","research","items","prestige"};string selected=names.Contains(game.NavigationTab)?game.NavigationTab:"research";for(int i=0;i<5;i++){bool active=selected==names[i];tabs[i].GetComponent<Image>().color=active?GameTheme.Hex("17353F"):Color.clear;var line=tabs[i].transform.Find("ActiveLine");if(line!=null)line.gameObject.SetActive(false);if(active&&indicator!=null){var parent=(RectTransform)indicator.transform.parent;float goal=parent.InverseTransformPoint(tabs[i].transform.position).x;bool reduced=s.Workshop.reducedMotion||!s.Settings.effects;if(!located||reduced)indicatorX=goal;else indicatorX=Mathf.Lerp(indicatorX,goal,1-Mathf.Exp(-Time.unscaledDeltaTime*20));located=true;indicator.rectTransform.anchoredPosition=new Vector2(Mathf.Round(indicatorX),3);indicator.rectTransform.sizeDelta=new Vector2(((RectTransform)tabs[i].transform).rect.width-20,3);}foreach(var t in tabs[i].GetComponentsInChildren<Text>())t.color=active?GameTheme.Accent:GameTheme.Muted;}Laboratory.gameObject.SetActive(game.CurrentTab=="hardware");}
 }
}
